<?php namespace App\Http\Controllers;
use App\Models\{Entry,Submission,Category}; use Illuminate\Http\Request; use Illuminate\Support\Facades\{Mail,Log}; use Illuminate\Support\Str;
class PortalController {
 public static function active(){return Entry::where('status','published')->where(fn($q)=>$q->where('type','!=','directory')->orWhereNull('category')->orWhereIn('category',Category::where('enabled',true)->select('name')))->where(fn($q)=>$q->whereNull('expires_at')->orWhere('expires_at','>',now()))->where(fn($q)=>$q->whereNull('deadline')->orWhere('deadline','>',now()))->where(fn($q)=>$q->whereNull('event_start')->orWhere('event_start','>',now()));}
 public function home(){return view('home',['categories'=>Category::where('enabled',true)->where('featured',true)->orderBy('sort_order')->get(),'groups'=>collect(['job','scholarship','event','news'])->mapWithKeys(fn($t)=>[$t=>self::active()->where('type',$t)->latest()->limit(4)->get()]),'featured'=>self::active()->where('type','directory')->whereNotNull('verified_at')->latest()->limit(6)->get()]);}
 public function categories(){return view('categories',['categories'=>Category::where('enabled',true)->orderBy('sort_order')->get(),'counts'=>self::active()->where('type','directory')->selectRaw('category,count(*) as total')->groupBy('category')->pluck('total','category')]);}
 public function category(Request $r,string $slug){$category=Category::where('slug',$slug)->where('enabled',true)->firstOrFail();return $this->index($r,'directory',$category);}
 public function index(Request $r,string $type,?Category $category=null){abort_unless(array_key_exists($type,config('obm.types')),404);$q=$this->active()->where('type',$type);if($category)$q->where('category',$category->name);$r->validate(['q'=>'nullable|string|max:100','country'=>'nullable|string|max:100','category'=>'nullable|string|max:120']);if(!$category&&$type==='directory'&&$r->filled('category')){$selected=Category::where('slug',$r->input('category'))->where('enabled',true)->first();if($selected)$q->where('category',$selected->name);else $q->whereRaw('1=0');}if($r->filled('q')){$s=mb_substr((string)$r->input('q'),0,100);$q->where(fn($a)=>$a->where('title','like','%'.$s.'%')->orWhere('title_bn','like','%'.$s.'%')->orWhere('summary','like','%'.$s.'%'));}if($r->filled('country'))$q->where('country',mb_substr((string)$r->input('country'),0,100));return view('entries',['category'=>$category,'directoryCategories'=>Category::where('enabled',true)->orderBy('sort_order')->get(),'type'=>$type,'entries'=>$q->latest()->paginate(24)->withQueryString(),'countries'=>$this->active()->where('type',$type)->whereNotNull('country')->distinct()->orderBy('country')->pluck('country')]);}
 public function show(string $slug){return view('entry',['entry'=>$this->active()->where('slug',$slug)->firstOrFail()]);}
 public function legacy(string $page='index'){ $map=['news-media'=>'news-media','education'=>'education','health'=>'health','government'=>'government','business'=>'business','travel'=>'travel','jobs'=>'jobs','abroad'=>'bangladesh-abroad','community'=>'community-resources'];if(isset($map[$page]))return redirect('/categories/'.$map[$page],301);if($page==='categories')return redirect('/categories',301);abort_unless(preg_match('/^[a-z0-9-]+$/D',$page),404);$file=resource_path('views/legacy/'.$page.'.html');abort_unless(is_file($file),404);$html=file_get_contents($file);$html=str_replace('href="styles.css"','href="/styles.css?v=4.4"',$html);$html=str_replace('https://www.onlinebanglamedia.com',rtrim(config('app.url'),'/'),$html);$html=preg_replace('~<nav\b[^>]*>.*?</nav>~is','',$html,1);$nav=view('public-nav')->render();$html=preg_replace_callback('~</header>~i',fn($m)=>$m[0].$nav,$html,1);$html=str_replace('</head>','<link rel="stylesheet" href="/portal-v44.css"></head>',$html);if($page==='index'){$html=preg_replace('/<main\b[^>]*>/i','$0'.view('ad-slot',['slot'=>'home_top'])->render(),$html,1);$html=str_replace('</main>',view('promotion')->render().view('ad-slot',['slot'=>'home_bottom'])->render().'</main>',$html);}elseif(in_array($page,['news-media','education','jobs','business','travel','categories','community','abroad'])){$html=str_replace('</main>',view('ad-slot',['slot'=>'category_bottom'])->render().'</main>',$html);}return response($html);}
 public function submit(Request $r){abort_if($r->filled('company_fax'),422);$data=$r->validate(['name'=>'required|string|max:150','email'=>'required|email:rfc|max:254','type'=>'required|in:new,correction,broken,job,scholarship,event,general','listing'=>'required|string|max:200','category'=>'nullable|string|max:100','region'=>'nullable|string|max:100','website'=>'nullable|url:http,https|max:2048','message'=>'required|string|max:4000','consent'=>'accepted']);unset($data['consent']);$s=Submission::create($data+['reference'=>strtoupper(Str::random(12)),'consented_at'=>now()]);try{Mail::raw("Reference: {$s->reference}\n".json_encode($data,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE),fn($m)=>$m->to(config('obm.recipient'))->replyTo($s->email)->subject('OBM submission '.$s->reference));$s->update(['emailed_at'=>now()]);}catch(\Throwable $e){Log::warning('Submission email failed',['id'=>$s->id]);}return back()->with('success','Submission saved for review. Reference: '.$s->reference);}
 public function sitemap(){ $urls=[url('/'),url('/submit')];$urls[]=url('/categories');foreach(['bangla','privacy','emergency'] as $p)$urls[]=url('/'.$p.'.html');foreach(Category::where('enabled',true)->get() as $c)if(self::active()->where('type','directory')->where('category',$c->name)->exists())$urls[]=url('/categories/'.$c->slug);foreach(config('obm.types') as $t=>$label)if($this->active()->where('type',$t)->exists())$urls[]=url('/opportunities/'.$t);foreach($this->active()->where(fn($q)=>$q->where('type','!=','directory')->orWhereNotNull('verified_at'))->select('slug')->cursor() as $e)$urls[]=url('/entry/'.$e->slug);$xml='<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">';foreach($urls as $u)$xml.='<url><loc>'.htmlspecialchars($u,ENT_XML1).'</loc></url>';return response($xml.'</urlset>',200,['Content-Type'=>'application/xml']);}
}
